// Authored S6 units and assessments. Objective ownership is explicit, not inferred from word overlap.
const ids = (r, ...ns) => ns.map((n) => `S6.${String(r).padStart(2, "0")}.A${String(n).padStart(2, "0")}`);
const asset = (name) => `/assets/course-v3/section-6/${name}`;
const table = (title, headers, rows) => ({ type: "table", title, headers, rows, preserveText: true });
const flow = (title, steps) => ({ type: "flow", title, steps, preserveText: true });
const worked = (title, steps) => ({ type: "worked-example", title, steps });
const visual = (title, name, facts, alt) => ({ type: "reviewed-visual", title, asset: asset(name), facts, alt, review: "reviewed", preserveText: true });
const oldVisual = (title, file, facts, alt) => ({ ...visual(title, file, facts, alt), asset: `/assets/diagrams/stage10-infographics/${file}` });
const unit = (key, heading, objectiveIds, explanation, materials, misconception, prompt, answer) => ({
  unitKey: `S6-${key}`, syllabusId: objectiveIds[0].replace(/\.A\d+$/, ""), heading, objectiveIds,
  explanation, materials: materials.map((m) => ({ ...m, objectiveIds })), misconceptions: [misconception],
  useAuthoredVisual: true, checkpoint: { prompt, answer },
});
const q = (lesson, n, prompt, objectiveIds, answerPoints, commonError, exam = false) => ({
  id: `S6-L0${lesson}-${exam ? "EXAM-" : "Q"}${n}`, type: "Application", authored: true,
  prompt, objectiveIds, answerPoints, marks: answerPoints.length, commonError,
});
const e = (lesson, n, ...args) => q(lesson, n, ...args, true);
const objective = (r, n, text) => [ids(r, n)[0], text];

const lessons = {
  1: {
    subtitle: "Distinguish three properties of data, then explain why both stored information and the processing system need protection.",
    guidingQuestion: "Can a file remain unchanged while its disclosure still causes a problem?",
    objectives: [objective(1, 1, "Distinguish data security, privacy and integrity using a stated situation."), objective(2, 1, "Explain why both data and the computer system need security.")],
    units: [
      unit("CONCEPTS", "Security, privacy and integrity", ids(1, 1), [
        "Data security protects information against unauthorised access, loss or damage. Privacy concerns the appropriate collection, use and disclosure of personal information. Data integrity concerns accuracy, completeness and consistency, including avoiding incorrect changes during processing or transfer.",
        "These concepts can be affected separately. Restricting access does not make an incorrect value true, and copying a record perfectly does not make its disclosure appropriate. Identify the property affected from what happened to the data, not simply from the presence of a password.",
      ], [table("Classify the consequence", ["Event", "Property to discuss", "Reason"], [["A private address list is published", "Privacy", "Personal information disclosed inappropriately"], ["A total changes from 250 to 520", "Integrity", "Stored value no longer matches the intended total"], ["An intruder deletes the only copy", "Security", "Unauthorised loss or damage"]])], "One incident may affect more than one property; the terms are not interchangeable.", "A locked file contains a mistyped date. Which property has not been ensured?", "Integrity: restricting access cannot correct a date that was entered wrongly."),
      unit("SYSTEM", "Protect the data and its processing system", ids(2, 1), [
        "A system must remain available to authorised users and must execute trusted operations. Malware, stolen credentials or damaged hardware can disrupt processing or expose data even when a separate file copy has been protected.",
        "Data also needs protection wherever copies are stored or transferred. A secured computer cannot prevent disclosure from an unencrypted removable drive that has already been lost. Combine system controls with protection of the data and recoverable copies.",
      ], [table("Two independent protection targets", ["Target", "Example failure", "Protection needed"], [["Computer system", "Attacker controls the running payroll application", "Secure execution and a recoverable system"], ["Data copy", "A lost drive exposes readable salary records", "Protect stored and transferred copies"]]), worked("A clinic cannot open its records", [["Situation", "The record files are encrypted, but malware prevents the appointment computer from starting."], ["Consequence", "Staff cannot use the records even though encryption still protects the files from casual reading."], ["Response", "Restore the system from a trusted source and recover records from tested backups; encryption alone cannot restore the service."]])], "Confidentiality alone is not enough when the service is unusable.", "Does locking the computer room protect a data copy sent to the wrong recipient?", "No. Physical protection of the computer does not control a copy after disclosure."),
    ],
    practice: [
      q(1, 1, "Identify the principal data concern in each case and justify it: a school publishes private medical details; a marks total is calculated incorrectly; an intruder destroys stored files.", ids(1, 1), ["Privacy: medical information is disclosed inappropriately.", "Integrity: the recorded result is inaccurate.", "Security: an unauthorised person causes data loss."], "Justify each classification from the event; accept a further property only with a valid explanation."),
      q(1, 2, "Explain why password protection does not ensure that an entered examination mark is accurate. Give an example of a protected but inaccurate value.", ids(1, 1), ["A password restricts access but does not compare the entered mark with its source.", "For example, an authorised teacher may enter 64 instead of the actual 46."], "A password is not a validation or verification check."),
      q(1, 3, "Explain why a company must protect its computer system as well as encrypt its stored customer files. Give two different consequences of system compromise.", ids(2, 1), ["Malware may prevent authorised staff from running the customer application.", "An attacker controlling an authenticated session may read or alter data after the application decrypts it."], "Relate the consequence to the running system rather than repeating that data is valuable."),
      q(1, 4, "Explain why securing a server room is insufficient when staff carry unencrypted copies of records on removable drives.", ids(2, 1), ["The removable copy is outside the protection of the server room.", "Someone finding the drive can read its contents unless the copy itself is protected."], "Consider the location of each copy."),
    ],
    authoredExamQuestions: [
      e(1, 1, "A survey database accurately stores named respondents' answers. An employee sends the unchanged records to an advertiser without permission. Explain the privacy and integrity implications separately.", ids(1, 1), ["The disclosure uses personal information for an unauthorised recipient or purpose, so privacy is affected.", "The unchanged answers may retain their accuracy and completeness; a privacy breach does not itself show corruption."], "Do not infer that accurate information may be disclosed without restriction."),
      e(1, 2, "A museum's encrypted catalogue survives an incident, but its only workstation cannot start. Explain why encryption has not preserved a usable service and suggest a suitable recovery measure.", ids(2, 1), ["Encryption protects readable contents rather than restoring a working operating system or application.", "Staff still require a functioning computer to retrieve and process the catalogue.", "A tested system backup or replacement workstation can restore the processing environment."], "The recovery measure must address the failed system."),
      e(1, 3, "A shop allows only managers to edit stock records. One manager enters 90 instead of 9. Explain what the access control achieved, what it did not achieve, and one check that could detect this error.", ids(1, 1), ["The edit was restricted to an authorised role.", "The permission check did not establish the correctness of the quantity.", "Comparing the saved quantity with the original stock count can expose the mismatch."], "An authorised change can still be incorrect."),
    ],
    summary: [["Security", "Protect against unauthorised access, loss and damage."], ["Privacy", "Control appropriate use and disclosure of personal information."], ["Integrity", "Preserve accurate, complete and consistent records."], ["Two protection targets", "Keep the processing service usable and protect its data copies."]],
  },
  2: {
    subtitle: "Follow each security mechanism separately: accounts, signatures, biometrics, traffic filtering and malware detection.",
    guidingQuestion: "Which mechanism checks identity, which checks a message, and which controls traffic?",
    objectives: [
      objective(3, 1, "Describe how user accounts and passwords support authentication."), objective(3, 2, "Describe the creation and verification of a digital signature."),
      objective(3, 3, "Explain biometric matching and its limitations."), objective(3, 4, "Describe firewall rules on a stand-alone PC and a network."),
      objective(3, 5, "Explain virus detection, updates and quarantine."), objective(3, 6, "Explain how anti-spyware detects and removes spyware."),
      objective(3, 7, "Explain the confidentiality role of encryption in system protection."), objective(3, 8, "Select complementary security controls for a stated system."),
    ],
    units: [
      unit("ACCOUNTS", "User accounts and passwords", ids(3, 1), [
        "A user account gives a person a distinct identity on a computer or network. The system associates that identity with permissions and an activity record. Separate accounts help attribute actions to individual users.",
        "A password is secret knowledge used to authenticate the claimed identity. The system checks the supplied password against the account's stored verifier before accepting the login. Hard-to-guess passwords and limits on repeated attempts reduce guessing; a disclosed password can still be misused.",
      ], [flow("Account login", [["Claim", "Enter an account identifier."], ["Evidence", "Supply the password for that account."], ["Authentication", "System checks the supplied evidence."], ["Authorisation", "Permissions decide which actions are allowed."]])], "Authentication establishes an identity claim; it does not grant every permission.", "Why should two staff members avoid sharing one account?", "The activity record no longer reliably distinguishes which member performed an action."),
      unit("SIGNATURE", "Create and verify a digital signature", ids(3, 2), [
        "The sender applies a hash algorithm to a message to produce a digest, then signs that digest using the sender's private key. In the simplified signing model, this is described as encrypting the digest. The sender sends the message together with the digital signature.",
        "The receiver uses the sender's public key to verify the signature; in the simplified model, decrypting the signature recovers the sender's digest. The receiver also hashes the received message with the same algorithm and compares the digests. A match supports the claimed origin and shows that the signed content has not changed, provided the public key is correctly associated with the sender.",
        "A digital signature does not make the message unreadable. Confidentiality requires encryption separately. Signing the digest must not be confused with sending the private key or merely appending an unprotected checksum.",
      ], [visual("Digital signature: sender and receiver", "digital-signature.png", ["Trace the upper sender lane before the two receiver branches.", "Compare both digest results at the orange decision."], "Sender hashes a message and signs its digest with a private key. Receiver hashes the received message and verifies the received signature with the sender's public key, then compares the two digest results."), worked("A signed purchase order changes", [["Original", "The supplier signs an order for 12 units and sends the order with its signature."], ["Alteration", "A third party changes the order to 120 units but retains the original signature."], ["Verification", "Hashing the altered order produces a different digest from the signed original, so the comparison fails."], ["Interpretation", "Do not accept the altered order as the originally signed content; the signature has not kept the order secret."]])], "The private key stays with the signer; the receiver uses the corresponding public key.", "If a message is signed but not encrypted, can an observer read it?", "Yes. A signature supplies authenticity and integrity evidence, not confidentiality."),
      unit("BIOMETRIC", "Biometric authentication", ids(3, 3), [
        "Biometrics use a physical or behavioural feature, such as a fingerprint, iris, voice or typing pattern. A sensor captures the feature and software extracts a template that is compared with an enrolled reference.",
        "A sufficient match authenticates the identity claim. False acceptance can admit an impostor, while false rejection can deny a legitimate user. Sensors and protected templates are needed, and a compromised biological feature cannot be replaced as easily as a password.",
      ], [oldVisual("Capture and match a biometric", "stage10-lesson-066-biometrics.jpg", ["Follow the sensor, extracted feature and reference template.", "Distinguish an incorrect acceptance from an incorrect rejection."], "Biometric sensor and template matching process, with separate explanations of false acceptance, false rejection and authorisation.")], "A biometric match is not the same as permission to modify every record.", "A registered user is rejected after a poor scan. Name the error.", "False rejection: a legitimate enrolled user has not been accepted."),
      unit("FIREWALL", "Firewalls on a PC and at a network boundary", ids(3, 4), [
        "A firewall checks incoming and outgoing traffic against configured rules, for example rules about addresses, ports, protocols or connection state. It allows permitted traffic and blocks disallowed traffic; it may also log decisions.",
        "A host firewall runs on one computer. A network firewall filters traffic passing through a network boundary. Neither arrangement guarantees that all harmful content is detected: permitted traffic can still carry a deceptive message or malicious download, and poorly chosen rules can leave unwanted access open.",
      ], [visual("Traffic decisions and firewall placement", "firewall.png", ["The orange connection stops at the filter.", "Compare the boundary around one host with the boundary around a LAN."], "Firewall compares incoming and outgoing traffic with example rules. Allowed traffic reaches the protected network and disallowed traffic stops. Host and network firewall placements are compared."), worked("Apply two traffic rules", [["Rules", "Allow inbound connections to the public web service; deny inbound connections to the staff file service."], ["Web request", "A request addressed to the permitted web service is allowed."], ["File request", "An external request addressed to the staff file service is blocked."], ["Limit", "An allowed web response may still contain unsafe content, so other controls remain necessary."]])], "A firewall makes traffic decisions; it does not authenticate the author of every message.", "Can a firewall inspect traffic that never passes through it?", "No. Its protection depends on placement and the traffic path."),
      unit("ANTIVIRUS", "Anti-virus software", ids(3, 5), [
        "Anti-virus software scans files, memory or activity for known virus signatures and suspicious behaviour. On detection it can block execution, isolate a file in quarantine, or remove the malicious code.",
        "Detection information must be updated as new threats are identified. Quarantine prevents normal use of a suspicious file while preserving it for review. New or concealed malware may escape detection, so a successful scan does not prove that every file is safe.",
      ], [flow("Respond to a suspicious executable", [["Scan", "Compare file patterns and behaviour with detection criteria."], ["Detect", "Flag a match or suspicious activity."], ["Contain", "Block execution or quarantine the file."], ["Maintain", "Update detection information and rescan as needed."]])], "Updates improve detection knowledge; they do not guarantee detection of every new variant.", "Why quarantine rather than immediately execute a suspicious attachment?", "Isolation prevents the suspected code from running while it is investigated."),
      unit("ANTISPYWARE", "Anti-spyware software", ids(3, 6), [
        "Anti-spyware looks for software that covertly monitors activity or collects information. It can detect a monitoring component, stop it, quarantine it or remove it. Detection may be included within a broader anti-malware product.",
        "Removing spyware reduces further collection but cannot retrieve information already sent to a third party. Exposed credentials may need replacing, and the entry route should be addressed to reduce reinfection.",
      ], [table("After detecting a keylogger", ["Action", "Purpose"], [["Stop or isolate the component", "Prevent further monitoring"], ["Remove the spyware", "Eliminate the detected installation"], ["Change exposed credentials", "Reduce misuse of already stolen secrets"], ["Update detection information", "Recognise newly identified spyware"]])], "Removing a keylogger does not undo an earlier password disclosure.", "A keylogger is removed today after sending yesterday's password. Is that password safe to retain?", "No. The recipient may already know it; replace the compromised credential."),
      unit("LAYERS", "Combine controls for different risks", ids(3, 7, 8), [
        "Encryption changes readable plaintext into ciphertext using an algorithm and key. It protects the confidentiality of stored or intercepted copies; the authorised application needs the correct key to recover readable data.",
        "Choose controls by mechanism. Login authentication checks identity, a firewall filters connections, anti-malware addresses malicious software, and encryption protects content outside normal access paths. Combining these controls reduces different risks without assuming that any one control replaces the others.",
      ], [table("A travelling employee's computer", ["Exposure", "Control", "What it addresses"], [["Guessed login", "Account and strong authentication", "Impersonation"], ["Unwanted inbound traffic", "Host firewall", "Disallowed connections"], ["Infected download", "Updated anti-virus", "Detected malicious execution"], ["Stolen storage drive", "Encryption", "Readable contents without the key"]])], "A list of security products is insufficient unless each choice is linked to a risk.", "Which listed control protects a stolen drive's readable contents?", "Encryption, provided the decryption key is not also available to the thief."),
    ],
    practice: [
      q(2, 1, "Describe how an account identifier and a password are used at login, and explain why separate staff accounts support accountability.", ids(3, 1), ["The identifier selects the identity being claimed.", "The system checks the supplied password for that account.", "Individual account records allow actions to be associated with a particular staff identity."], "Do not treat an account name alone as proof of identity."),
      q(2, 2, "Describe the sender and receiver stages used to create and check a digital signature for a document.", ids(3, 2), ["The sender hashes the document to obtain a digest.", "The sender signs the digest using the private key.", "The document and signature are sent together.", "The receiver verifies the signature using the sender's public key.", "The receiver hashes the received document with the same algorithm.", "The receiver compares the digests to check origin and unchanged content."], "The receiver must calculate a digest as well as verify the signature."),
      q(2, 3, "Explain how a fingerprint system authenticates a claimed user and distinguish false acceptance from false rejection.", ids(3, 3), ["A sensor captures the fingerprint and software extracts identifying features.", "The resulting template is compared with the enrolled reference.", "False acceptance admits an impostor; false rejection denies a legitimate user."], "Do not exchange the two error names."),
      q(2, 4, "A PC allows incoming connections to service X and blocks service Y. Describe the firewall decision for a request to Y and compare host and network firewall placement.", ids(3, 4), ["The destination service is checked against the rules and the request to Y is blocked.", "A host firewall filters traffic for the individual PC.", "A network firewall filters traffic traversing the network boundary."], "Blocking follows the rule, not a guarantee that the request contains a virus."),
      q(2, 5, "Explain why anti-virus software needs updates and describe two actions it may take after detecting an infected file.", ids(3, 5), ["Updates provide information for recognising newly identified viruses.", "It may quarantine the file to prevent normal execution.", "It may remove the malicious code or delete the infected file."], "Give two different responses rather than two descriptions of scanning."),
      q(2, 6, "Describe what anti-spyware can do about an installed screen-monitoring program and explain why removal may not end every consequence.", ids(3, 6), ["It can identify the monitoring program using detection rules or suspicious behaviour.", "It can stop, isolate or remove the detected component.", "Previously transmitted screenshots may remain with the recipient."], "Stopping future collection cannot erase a recipient's existing copy."),
      q(2, 7, "Suggest a control for each risk and explain the match: stolen laptop storage, unauthorised inbound connections, and an infected program. Explain why the first control cannot replace the other two.", ids(3, 7, 8), ["Encrypt the storage so its contents cannot be read without the key.", "Use a firewall to reject connections disallowed by its rules.", "Use anti-virus software to detect and isolate infected code.", "Encryption does not filter live connections or decide whether a program is malicious."], "Link each control to its own mechanism."),
    ],
    authoredExamQuestions: [
      e(2, 1, "A signed delivery instruction is altered from warehouse A to warehouse B while its original signature is retained. Explain how the receiver can detect the alteration and why signing alone does not conceal either address.", ids(3, 2), ["The receiver obtains the digest evidence from the original signature using the sender's public key.", "Applying the agreed hash algorithm to the altered instruction produces a new digest.", "The new digest fails to match the signed digest, so the received content cannot be accepted as unchanged.", "The instruction itself remains readable when no separate encryption has been applied."], "Do not claim that the signature must change when an attacker edits only the message."),
      e(2, 2, "A library permits web browsing through its firewall. A user downloads a malicious executable over an allowed connection. Explain why this is possible, how anti-virus can respond, and one reason a scan may miss the threat.", ids(3, 4, 5), ["The connection can satisfy the firewall's traffic rules even though the downloaded content is harmful.", "Anti-virus can inspect the executable for recognised patterns or suspicious behaviour.", "It can prevent execution by isolating the detected file.", "An unfamiliar or concealed variant may not be recognised by the available detection information."], "Do not describe firewall filtering as universal content detection."),
      e(2, 3, "A laboratory uses individual accounts and iris scans. It also detects spyware on a terminal and encrypts exported results. Explain the distinct role of each of these four controls, including one consequence that spyware removal cannot reverse.", ids(3, 1, 3, 6, 7, 8), ["Individual accounts associate permitted activity with separate identities.", "An iris scan provides physical identity evidence for comparison with an enrolled template.", "Anti-spyware can remove the monitoring component to stop further collection.", "It cannot recover results or credentials already disclosed to an attacker.", "Encryption protects the readable contents of an exported copy from a person without its decryption key."], "Keep identity checks, monitoring detection and confidentiality separate."),
    ],
    summary: [["Identity", "An account names the user; a password or biometric supplies evidence."], ["Signed messages", "Hash, sign, send, verify and compare; confidentiality is separate."], ["Traffic", "Firewall rules apply to the connections passing through the filter."], ["Malware", "Detection, containment and current detection information reduce risk."], ["Layers", "Choose a different mechanism for each exposure."]],
  },
  3: {
    subtitle: "Distinguish malware, unauthorised access, phishing and pharming, then match precautions to the route of each threat.",
    guidingQuestion: "Did the attack execute code, gain access, deceive a person or redirect a destination?",
    objectives: [objective(4, 1, "Explain how a virus infects a host and threatens data or a system."), objective(4, 2, "Explain how spyware collects and discloses information."), objective(4, 3, "Explain the risk of unauthorised access by hackers."), objective(4, 4, "Explain how a phishing message deceives a user."), objective(4, 5, "Explain how pharming redirects a user to a fraudulent site."), objective(5, 1, "Select and describe precautions whose mechanisms restrict a stated threat.")],
    units: [
      unit("VIRUS", "Viruses attach to a host and replicate", ids(4, 1), [
        "A virus is malicious code that attaches to or modifies a host file or program. Running the infected host can execute the virus and allow it to replicate into further files. Its payload may corrupt information, delete data or disrupt the computer.",
        "Networks, shared files and downloaded attachments provide routes for infected hosts to reach other computers. Avoid executing untrusted files and use maintained detection software to reduce this risk.",
      ], [flow("Follow an infected host", [["Arrival", "An infected program is downloaded."], ["Execution", "The user runs its host program."], ["Replication", "Viral code infects additional host files."], ["Impact", "Data or normal processing may be damaged."]])], "A virus is code, not a person gaining unauthorised access.", "Which event activates the virus in this model: downloading or running the infected host?", "Running the host executes the attached code; merely describing a download is not a complete mechanism."),
      unit("SPYWARE", "Spyware monitors and discloses", ids(4, 2), [
        "Spyware covertly monitors activity or collects data, for example by logging keystrokes or recording the screen. Collected information may be sent to a third party, exposing private details or credentials.",
        "Its defining feature is covert collection, not necessarily self-replication. Anti-spyware can address the installed component, while controlled installation and caution with downloads reduce entry opportunities.",
      ], [oldVisual("The collection and disclosure route", "stage10-lesson-064-spyware.jpg", ["Follow monitoring into the disclosure of credentials.", "Distinguish removal of software from recovery of disclosed information."], "Spyware examples show keystroke and screen monitoring, disclosure risks and precautions against installation.")], "Do not substitute a virus replication explanation for spyware's collection mechanism.", "Why can a keylogger threaten an account on a different website?", "It may capture that website's credentials when the user types them and disclose them to an attacker."),
      unit("HACKING", "Unauthorised access by hackers", ids(4, 3), [
        "In this security context, a hacker gains or attempts unauthorised access to a system or its data. Weak credentials, exposed services or unpatched vulnerabilities can provide an entry route.",
        "The resulting access may permit disclosure, alteration or disruption. Strong authentication reduces impersonation, software patches address known vulnerabilities, and access rights limit what a compromised account can do.",
      ], [table("Entry route and consequence", ["Entry route", "Possible consequence", "Matching control"], [["Guessed password", "Account impersonation", "Strong authentication and attempt limits"], ["Unpatched service", "Execution through a known flaw", "Install security patches"], ["Excessive permissions", "Unnecessary records exposed", "Least privilege"]])], "Successful login using stolen credentials can still be unauthorised access.", "A stolen student password works. Does that make the intruder authorised?", "No. Possessing the secret does not give the intruder legitimate permission."),
      unit("PHISHING", "Phishing persuades the user", ids(4, 4), [
        "A phishing message impersonates a trusted organisation or person and persuades the recipient to disclose information or perform an unsafe action. It may use urgency and a link to a fake sign-in page to capture credentials.",
        "Check the request through an independently obtained contact or known website rather than the message's link. Filtering and training reduce exposure; multi-factor authentication can reduce the impact of a stolen password but does not make every deceptive request harmless.",
      ], [flow("A deceptive sign-in request", [["Impersonation", "Message claims to come from school support."], ["Pressure", "It says the account will close today."], ["Interaction", "User follows a link to a copied sign-in page."], ["Disclosure", "The entered password goes to the attacker."]]), worked("Verify a payment change", [["Message", "An email asks the bursar to use a new bank account immediately."], ["Independent check", "The bursar calls the supplier using the number already held in the supplier register."], ["Decision", "The supplier denies the change, so the request is rejected without using contact details from the email."]])], "A convincing logo or urgent tone is not proof of the sender's identity.", "Why should the phone number in the suspicious email not be used to verify it?", "The attacker may control that number as well as the message."),
      unit("PHARMING", "Pharming changes the destination", ids(4, 5), [
        "Pharming redirects a user to a fraudulent site, for example by corrupting DNS or local name-resolution information. The user may type the intended address correctly yet be directed to a different destination.",
        "Protect name-resolution settings, update affected software and investigate certificate or hostname warnings. An HTTPS indicator alone does not prove that a site is legitimate; examine the intended destination and do not ignore a certificate mismatch.",
      ], [table("Similar outcome, different route", ["Phishing", "Pharming"], [["Deceptive message encourages an action", "Name resolution or routing information is manipulated"], ["User is persuaded to follow the supplied route", "Correctly entered address can still be redirected"], ["Verify requests independently", "Protect resolution settings and investigate certificate warnings"]])], "Not every fake website visit is pharming; identify how the destination was selected.", "A correct typed address resolves through a corrupted hosts entry. Which threat fits?", "Pharming: the destination has been redirected without requiring a deceptive link."),
      unit("RISK", "Match precautions to the threat", ids(5, 1), [
        "A useful precaution interrupts a specific route or reduces a specific consequence. Explain that link: patching repairs a known software weakness, permission restrictions reduce exposure, and independent verification challenges a deceptive request.",
        "Controls reduce risk rather than eliminate every possible incident. Combining prevention, detection and recovery allows a response when one measure fails. Choose controls appropriate to the system and explain what remains outside each control's role.",
      ], [table("Choose from the mechanism", ["Threat", "Precaution", "Reason"], [["Infected attachment", "Scan and avoid untrusted execution", "Interrupt malicious code running"], ["Hidden keylogger", "Anti-spyware and controlled installation", "Detect monitoring and reduce entry"], ["Credential guessing", "Strong authentication", "Make impersonation harder"], ["Fake payment email", "Independent confirmation", "Test the claimed request"], ["Corrupted name resolution", "Protect settings and patch software", "Reduce redirection opportunities"]])], "Encryption of a file does not decide whether an email is a truthful request.", "Can a backup prevent phishing?", "No. It supports recovery after loss; it does not authenticate a message or prevent disclosure."),
    ],
    practice: [
      q(3, 1, "Describe how an infected shared program can spread a virus and state one possible effect on the receiving computer.", ids(4, 1), ["Viral code is attached to the shared host program.", "Running the infected host allows the code to execute and replicate into other files.", "It may corrupt data, delete files or disrupt processing."], "Give the host and execution stages, not just the word malware."),
      q(3, 2, "Explain how spyware that records keystrokes could compromise a user's email account.", ids(4, 2), ["The program covertly records the account identifier and password as they are typed.", "It transmits the captured credentials to a third party.", "The third party can attempt to impersonate the user at the email service."], "Identify the collected information and its consequence."),
      q(3, 3, "Explain how an unpatched network service can enable unauthorised access and how patching restricts this risk.", [...ids(4, 3), ...ids(5, 1)], ["An attacker may exploit a known flaw in the exposed service.", "The exploit may allow actions without legitimate permission.", "A relevant patch repairs the flaw that provided this entry route."], "Patching a software flaw is different from changing a weak password."),
      q(3, 4, "An email says a student's account will close unless they sign in through its link. Explain two features of this phishing route and describe one suitable precaution.", [...ids(4, 4), ...ids(5, 1)], ["The sender impersonates a trusted service and uses urgency.", "The link can deliver credentials to a fraudulent page.", "Open the known school site independently or contact school support using trusted details."], "Do not verify a suspicious link by entering a real password into it."),
      q(3, 5, "Describe how corrupting local name-resolution information can cause pharming even when a user types the correct address. State a suitable precaution.", [...ids(4, 5), ...ids(5, 1)], ["The typed name is translated using the corrupted mapping.", "The resulting destination is an attacker-controlled site rather than the intended server.", "Restrict changes to name-resolution settings and investigate unexpected certificate warnings."], "A deceptive email is not necessary for this route."),
      q(3, 6, "Suggest two different precautions for a shared computer where users install unknown downloads, and explain the specific risk addressed by each.", ids(5, 1), ["Restrict software installation to reduce unapproved executable code entering the system.", "Maintain anti-malware scanning to detect and isolate malicious code that still reaches the computer."], "Accept another control only when its mechanism addresses the stated installation risk."),
    ],
    authoredExamQuestions: [
      e(3, 1, "Two staff members reach fake banking pages. Staff member A follows an urgent text-message link. Staff member B types the correct address, but a modified local lookup sends them elsewhere. Identify each threat and explain one suitable precaution for each route.", [...ids(4, 4, 5), ...ids(5, 1)], ["A is phishing because a deceptive communication persuades the recipient to use a supplied link.", "B is pharming because the destination mapping redirects a correctly entered name.", "A should reach the bank through an independently known address or contact.", "B's device needs protected or repaired name-resolution settings, with suspicious certificate warnings investigated."], "Distinguish the route, not simply the appearance of the fake page."),
      e(3, 2, "A downloaded utility copies code into other executable files and silently sends typed account details to an outsider. Explain why both virus and spyware descriptions apply, and suggest an appropriate detection response.", ids(4, 1, 2), ["Infecting other executable hosts is viral replication.", "Secretly collecting and sending typed credentials is spyware activity.", "Updated anti-malware capable of virus and spyware detection can scan and isolate the utility and affected files."], "One malicious program may have more than one behaviour."),
      e(3, 3, "An intruder uses a guessed receptionist password. The account can read appointment times but cannot edit medical records. Explain the unauthorised-access risk, what the restricted permissions achieved, and a precaution against a repeat login.", [...ids(4, 3), ...ids(5, 1)], ["The intruder impersonates the receptionist and can disclose information readable by that account.", "The lack of write permission limits alteration of medical records despite the successful login.", "A harder-to-guess password, attempt limits or an additional authentication factor reduces this entry risk."], "Permissions reduce the impact but do not make the stolen identity legitimate."),
    ],
    summary: [["Virus", "Host infection and replication can damage processing or data."], ["Spyware", "Covert collection can disclose activity and credentials."], ["Hacking", "Unauthorised access exploits credentials or system weaknesses."], ["Phishing and pharming", "Distinguish persuasion from destination redirection."], ["Precautions", "Name the interrupted route or reduced consequence."]],
  },
  4: {
    subtitle: "Follow encryption and decryption, then use an access-rights matrix to decide permitted file operations.",
    guidingQuestion: "What protects a stolen copy, and what controls an authorised user's actions?",
    objectives: [objective(6, 1, "Describe encryption and decryption as protection for data confidentiality."), objective(6, 2, "Apply access rights to data operations and explain their limits.")],
    units: [
      unit("ENCRYPTION", "Encryption and decryption", ids(6, 1), [
        "Encryption applies an algorithm and key to plaintext, producing ciphertext. Decryption applies the corresponding algorithm and correct key to recover the original readable information. An intercepted or stolen encrypted copy should be unintelligible to someone without the required key.",
        "Protect the key separately from the encrypted copy. Encryption does not decide which logged-in user may edit a record, prevent deletion of ciphertext, or prove that the source data was true. Its main role here is confidentiality.",
      ], [visual("From readable data to a protected copy", "encryption.png", ["Follow all five stages from plaintext to recovered plaintext.", "The branch under ciphertext represents an intercepted copy."], "Plaintext passes through encryption with a key into ciphertext; decryption with the correct key recovers plaintext. An interceptor without that key cannot read the contents. Access rights have a separate operational role."), worked("An encrypted archive on a lost drive", [["Stored copy", "An employee exports an encrypted archive, keeping its decryption key separately."], ["Drive lost", "The finder has the ciphertext but not the correct key, so cannot normally read the archive."], ["Remaining risk", "The finder can still erase the drive; another recoverable copy is needed for availability."], ["Key also disclosed", "If the required key is later disclosed, the confidentiality protection of that copy is lost."]])], "Encryption can protect a stolen copy's contents without preventing that copy from being destroyed.", "What must the intended receiver have to recover the readable message?", "The correct decryption key and the corresponding decryption method."),
      unit("RIGHTS", "Apply access rights to data", ids(6, 2), [
        "Access rights associate users or roles with permitted actions on a resource. Read permits viewing, modify permits alteration, and delete permits removal. A service checks the requested operation against these permissions after identifying the user.",
        "Least privilege gives a role only the rights needed for its work. Restricting read access supports confidentiality; restricting changes supports integrity. Rights on a server do not protect an unencrypted copy outside that server, and authorised users can still make mistakes.",
      ], [table("Personnel-file permissions", ["Role", "Read", "Modify", "Delete"], [["Payroll clerk", "Allow", "Allow", "Deny"], ["Department manager", "Allow", "Deny", "Deny"], ["Visitor", "Deny", "Deny", "Deny"]]), worked("Evaluate three requests", [["Clerk edits salary", "Modify is allowed, so the service permits the operation."], ["Manager deletes a record", "Delete is denied, so the service rejects the request even after successful login."], ["Visitor reads a copied file", "The server matrix is not consulted for an external unencrypted copy; that copy needs its own protection."]])], "Knowing who logged in is not the same as permitting the operation they request.", "Which two rights let a user inspect and amend a record but not remove it?", "Read and modify; do not grant delete."),
    ],
    practice: [
      q(4, 1, "Describe how a sender makes a readable data file unintelligible during transfer and how the intended receiver restores it.", ids(6, 1), ["The sender encrypts plaintext with an algorithm and key to produce ciphertext.", "The receiver uses the correct decryption key and algorithm to recover the plaintext."], "Distinguish ciphertext from a hash digest."),
      q(4, 2, "Explain why keeping an unprotected decryption key on the same lost drive as an encrypted archive weakens its confidentiality protection.", ids(6, 1), ["The finder obtains the information needed to decrypt the archive as well as the ciphertext.", "Using that key may allow recovery of the readable records."], "The key needs protection as well as the encrypted file."),
      q(4, 3, "Using the personnel-file permissions table, state whether a payroll clerk may modify a record, a department manager may delete one, and a visitor may read one. Explain why successful login does not change these decisions.", ids(6, 2), ["The clerk may modify the record.", "The manager may not delete it.", "The visitor may not read it.", "Authentication does not replace the operation-specific permission checks."], "Apply each row and operation rather than assuming every logged-in user has full access."),
      q(4, 4, "Suggest rights for an auditor who must view invoices without changing or removing them. Explain why these rights do not protect an unencrypted invoice copied to an outsider's drive.", ids(6, 2), ["Grant read but deny modify and delete.", "The outsider reads a separate copy without consulting the original system's permission checks."], "Permissions are enforced by the system controlling the resource."),
    ],
    authoredExamQuestions: [
      e(4, 1, "A charity sends donor records to a contractor. Explain how encryption protects the transfer and why giving the contractor the key does not limit which records they may later change in the charity's database.", ids(6, 1, 2), ["Encryption transforms the transmitted records into ciphertext that an interceptor cannot normally understand.", "The contractor needs the correct key to recover the sent contents.", "Database changes are controlled by the contractor account's permissions, not by possession of the transfer key."], "Separate decrypting a copy from editing the source database."),
      e(4, 2, "A research assistant must add observations and correct their own entries; a reviewer must only read them. Suggest suitable permissions for each role and explain how this arrangement supports data integrity without proving that an observation is true.", ids(6, 2), ["Allow the assistant to create observations and modify only their own records.", "Give the reviewer read access without modification rights.", "Restricting changes reduces alteration by users who have no editing role.", "An authorised assistant may still record an incorrect observation, so permission does not establish truth."], "Use the stated resource scope, not unrestricted write access to all records."),
      e(4, 3, "An attacker erases an encrypted backup but never discovers its key. Explain the different effects on confidentiality and availability, then suggest a way to improve recovery.", ids(6, 1), ["The attacker has not gained readable content, so the incident does not itself demonstrate lost confidentiality.", "Erasing the backup removes that recovery copy and therefore harms availability.", "A separate protected backup copy allows recovery if one copy is destroyed."], "Do not claim encryption makes data undeletable."),
    ],
    summary: [["Transform", "Plaintext becomes ciphertext; the correct key enables recovery."], ["Protect the key", "An exposed key can expose an encrypted copy."], ["Permit operations", "Read, modify and delete are separate decisions."], ["Combine controls", "Encryption protects contents; permissions govern use of controlled resources."]],
  },
  5: {
    subtitle: "Apply validation rules, compare entered data with its source, and calculate checks for transmitted data.",
    guidingQuestion: "Does the value satisfy a rule, agree with its source, or reveal a transmission error?",
    objectives: [
      objective(7, 1, "Distinguish validation from verification in a stated situation."), objective(7, 2, "Apply a range check using both lower and upper bounds."),
      objective(7, 3, "Apply a format check to a required character pattern."), objective(7, 4, "Apply a length check to a number of characters."),
      objective(7, 5, "Apply a presence check to a required field."), objective(7, 6, "Apply an existence check against stored lookup data."),
      objective(7, 7, "Apply a limit check using one lower or upper bound."), objective(7, 8, "Calculate and verify a check digit using a given rule."),
      objective(7, 9, "Explain how validation supports integrity without proving truth."),
      objective(8, 1, "Use a visual comparison with the original data source."), objective(8, 2, "Use double entry and compare independently entered copies."),
      objective(8, 3, "Calculate byte parity and use block parity to locate a single-bit error."), objective(8, 4, "Calculate and compare a checksum using a stated algorithm."),
      objective(8, 5, "Explain the limitations of verification during entry and transfer."),
    ],
    units: [
      unit("VALIDATION", "Validation and verification answer different questions", ids(7, 1, 9), [
        "Validation tests whether input satisfies stated rules and is reasonable for its purpose. Verification checks whether information has been entered, copied or transferred accurately relative to its source. Both reduce the acceptance of errors and so help maintain data integrity.",
        "A plausible wrong value can pass validation, and two copies of a false original can agree. Neither process proves that the source is true. Use both when a system needs acceptable values and faithful copying.",
      ], [table("A source mark of 46 is entered as 64", ["Check", "Test", "Result"], [["Validation", "Is the mark between 0 and 75?", "64 passes"], ["Verification", "Does the entry match the source value 46?", "Mismatch detected"]])], "Passing a rule does not prove agreement with the source.", "Both source and entered age say 200; the allowed range is 0 to 120. Which process rejects it?", "Validation rejects the age. A comparison with that source would find agreement."),
      unit("BOUNDS", "Range and limit checks", ids(7, 2, 7), [
        "A range check applies both a lower and an upper bound, such as 0 <= Mark <= 75. Test both endpoints as well as values outside them; the stated rule decides whether the bounds are inclusive.",
        "A limit check applies one upper or lower bound, such as FileSize <= 10 MiB. It does not introduce a second bound that was not specified. Choose a range when both ends matter and a limit when the requirement supplies one bound.",
      ], [table("Apply the written bounds", ["Rule", "Value", "Decision"], [["0 <= Mark <= 75", "0; 75", "Both pass"], ["0 <= Mark <= 75", "-1; 76", "Both fail"], ["FileSize <= 10 MiB", "10 MiB; 11 MiB", "Pass; fail"]]), worked("Test an inclusive temperature range", [["Rule", "Accept temperatures from -20 to 50 degrees Celsius inclusive."], ["Endpoints", "-20 and 50 pass because equality is included."], ["Outside", "-21 and 51 fail because they lie beyond a bound."], ["Single-bound alternative", "A minimum-only limit Temperature >= -20 would accept 51; it does not impose the upper bound."]])], "Do not describe a one-sided limit as if it also enforced an unstated second limit.", "Does 75 pass the rule 0 <= Mark < 75?", "No. The upper comparison is strict, so 75 is excluded."),
      unit("PATTERNS", "Format and length checks", ids(7, 3, 4), [
        "A format check tests a required pattern, for example two uppercase letters followed by four digits. A length check tests the number of characters, for example exactly six. The two checks ask different questions about the same string.",
        "A six-character value can still have the wrong format. Check the complete pattern and the specified character count, preserving leading zeros when a code is a string.",
      ], [table("Code rule: two uppercase letters, then four digits", ["Input", "Length = 6", "Required format"], [["AB0123", "Pass", "Pass"], ["A10123", "Pass", "Fail"], ["AB123", "Fail", "Fail"]])], "The correct length alone does not establish the correct character pattern.", "Does 123456 satisfy both rules in the table?", "It passes length but fails format because the first two characters are not uppercase letters."),
      unit("PRESENCE", "Presence and existence checks", ids(7, 5, 6), [
        "A presence check requires an entry rather than a blank required field. An existence check looks for the supplied value in a specified stored lookup or file, such as checking that a customer identifier belongs to an existing customer.",
        "A value can be present but absent from the lookup. Define which field is required and which stored set supplies valid identifiers; do not confuse these checks with a format test.",
      ], [table("Stored customer IDs: C102, C107, C115", ["Entered ID", "Presence", "Existence in lookup"], [["Blank", "Fail", "No lookup match"], ["C107", "Pass", "Pass"], ["C999", "Pass", "Fail"]])], "A non-empty identifier is not evidence that the referenced record exists.", "An order names C999. What extra information is needed to check existence?", "The stored customer lookup against which C999 will be searched."),
      unit("CHECK-DIGIT", "Calculate and check an identifier's check digit", ids(7, 8), [
        "A check digit is derived from the other digits in an identifier and stored with them. On entry or scanning, the system repeats the stated calculation and compares the expected check digit with the supplied digit. A mismatch causes rejection or re-entry.",
        "Use the algorithm given in the question: different schemes use different weights and moduli. For the example here, multiply the four data digits by 3, 1, 3, 1 and choose a final digit that makes the total a multiple of 10. Some errors can still produce the same check digit.",
      ], [visual("Weighted check digit: a complete calculation", "check-digit.svg", ["Four data digits produce the weighted total shown.", "The final digit completes the next multiple of ten."], "Worked identifier 4726 with weights 3,1,3,1 gives products 12,7,6,6, total 31 and check digit 9, making code 47269."), worked("Verify a scanned code", [["Received code", "The scanner returns 47268; its last digit is the supplied check digit 8."], ["Recalculate", "4 x 3 + 7 x 1 + 2 x 3 + 6 x 1 = 31."], ["Compare", "The expected final digit is 9, so the supplied 8 does not match."], ["Decision", "Reject or request re-entry; the check does not identify with certainty which digit was mistyped."]])], "The final check digit is not another data digit to which the four supplied weights are applied.", "If the weighted total is already 40, what check digit is needed?", "0: the total already is a multiple of 10."),
      unit("ENTRY", "Verify entered data", ids(8, 1, 2), [
        "For a visual check, a person compares the entered value with the original source and investigates differences. It is a comparison with a source, not simply a judgement that the value looks reasonable.",
        "For double entry, the value is entered independently twice and the computer compares the entries. A mismatch is flagged for correction or re-entry. Agreement still cannot establish that the original source is correct, and repeating the same mistake can evade detection.",
      ], [table("Source code: BK209", ["Attempt", "Entered data", "Comparison"], [["Visual check", "BK290", "Compare with BK209: mismatch"], ["Double entry", "BK209 and BK290", "Two copies differ"], ["Repeated mistake", "BK290 and BK290", "Copies agree despite wrong source copying"]]), worked("Resolve a double-entry mismatch", [["Entries", "First operator enters 8371; second operator enters 8731."], ["Comparison", "The computer finds different strings and flags the entry."], ["Resolution", "Compare against the original form, which reads 8371, then correct and check again."]])], "Double entry compares copies; it does not use a numeric average of them.", "Source 640 is entered as 604 twice. Does double entry detect the mistake?", "No. Both entered copies agree, so an independent source comparison is still useful."),
      unit("BYTE-PARITY", "Use parity on a byte", ids(8, 3, 5), [
        "A parity bit is chosen so the total number of 1 bits, including that bit, has the agreed even or odd parity. The examples use seven data bits and one parity bit to form an eight-bit transmitted group.",
        "The receiver counts the 1s and compares the result with the agreed convention. Any odd number of flipped bits changes parity and is detected. An even number of flips can leave parity unchanged; the check alone cannot identify the incorrect bit or prove the byte is correct.",
      ], [visual("Build an even-parity byte", "byte-parity.svg", ["Count the data's set bits before choosing its parity bit.", "The receiver checks the complete transmitted group."], "Seven data bits 1011001 have four ones, so even parity adds 0 to send 10110010. Received 10100010 has three ones and fails even parity."), worked("An undetected two-bit change", [["Sent", "Even-parity byte 10110010 contains four 1 bits."], ["Two flips", "If its first two bits flip, the receiver gets 01110010."], ["Test", "The received byte still contains four 1 bits, so it passes even parity despite different data."]])], "Passing parity means no parity error was detected; it is not proof of an error-free transfer.", "Under odd parity, should the parity bit for data 1110000 be 0 or 1?", "0: there are already three 1 bits, an odd total."),
      unit("BLOCK-PARITY", "Use row and column parity", ids(8, 3, 5), [
        "Block parity organises transmitted groups into rows, applies a parity bit to each row, and adds a parity row or byte for the columns. The receiver checks parity in both directions using the agreed convention.",
        "If exactly one bit has changed, the failing row and failing column intersect at that bit, allowing it to be located and corrected by flipping it. Multiple errors may be ambiguous or undetected; four flipped corner bits in a rectangle leave every affected row and column parity unchanged.",
      ], [visual("Locate a single-bit error by intersection", "block-parity.svg", ["The bottom row contains the transmitted column parity bits.", "The highlighted row and column identify one changed bit in the received block."], "A received block of three eight-bit rows and a transmitted column parity row is shown after a flip in row 2 column 5. The failing row and column intersect at the changed bit; the original second row is supplied below."), worked("Correct the illustrated received block", [["Row checks", "In the received block, row 2 has odd rather than even parity."], ["Column checks", "Column 5 also has odd parity; the other rows and columns satisfy the rule."], ["Locate", "Assuming one changed bit, it is at row 2, column 5."], ["Correct and recheck", "Change that bit from 1 back to 0. Recompute both directions to confirm the block satisfies even parity."]])], "Locating an error depends on the error pattern; do not promise correction of every corrupted block.", "What can happen if the four corners of a rectangle all flip?", "Each affected row and column has two changes, so all parity checks can still pass."),
      unit("CHECKSUM", "Calculate and compare a checksum", ids(8, 4, 5), [
        "The sender calculates a value from a data block using an agreed checksum algorithm and sends it with the data. The receiver applies the same algorithm to the received block and compares its result with the transmitted checksum.",
        "A mismatch indicates an error and can trigger rejection or retransmission. A match means no error was detected by that checksum; different data can produce the same value. Use the stated algorithm rather than assuming that all checksums are simple sums.",
      ], [visual("An eight-bit sum checksum", "checksum.svg", ["The example algorithm keeps the sum modulo 256.", "Compare the receiver's recomputed value with the transmitted value."], "Sender sums 84,121,77 to 282 and sends checksum 26 modulo 256. Received data 84,120,77 gives 281 modulo 256, or 25, so the checksums differ."), worked("A matching checksum can miss an error", [["Original block", "84 + 121 + 77 = 282; this example's checksum is 26."], ["Changed block", "85 + 120 + 77 is also 282."], ["Limitation", "The two opposite changes cancel in the sum, so checksum 26 matches even though two data values differ."]])], "A checksum is used on a transferred block; a check digit is attached to an identifier under a validation rule.", "The received and recomputed checksums differ. What should the receiver conclude?", "An error was detected; do not accept the block as verified. Reject it or request retransmission."),
    ],
    practice: [
      q(5, 1, "A source form says 28 but 82 is entered. The allowed range is 0 to 100. Explain the validation result and the result of comparison with the source.", ids(7, 1, 9), ["82 satisfies the range, so that validation check passes.", "82 differs from 28, so source verification detects a copying error.", "This shows that a valid value need not be the true or intended value."], "Keep rule compliance separate from faithful copying."),
      q(5, 2, "State which values pass -10 <= Temperature <= 40 from -11, -10, 40 and 41. Then apply the single limit Temperature >= -10 to the same values and explain the difference.", ids(7, 2, 7), ["The range accepts -10 and 40 only.", "The limit accepts -10, 40 and 41.", "The range has an upper bound as well as a lower bound; the stated limit has only a lower bound."], "Include the endpoints where equality is allowed."),
      q(5, 3, "A code must contain exactly six characters in the format two uppercase letters followed by four digits. State the length and format result for AB1234, 123456 and AB123.", ids(7, 3, 4), ["AB1234 passes length and format.", "123456 passes length but fails format.", "AB123 fails both the length and the specified format."], "Assess each check independently."),
      q(5, 4, "The stored product IDs are P10 and P20. Apply presence and existence checks to a blank entry, P20 and P99, and state what each check tests.", ids(7, 5, 6), ["Presence tests for a non-blank required entry; the blank fails.", "Existence tests for membership in the stored product lookup.", "P20 is present and exists.", "P99 is present but does not exist in that lookup."], "A supplied value can fail existence without failing presence."),
      q(5, 5, "Calculate the check digit for data digits 5834 using weights 3,1,3,1. Choose the digit that makes the weighted total plus that digit a multiple of 10. State whether code 58345 passes.", ids(7, 8), ["The products are 15, 8, 9 and 4.", "Their total is 36, so the check digit is 4.", "58345 fails because its supplied check digit 5 differs from the calculated 4."], "The weight rule applies to the four data digits, not the appended check digit."),
      q(5, 6, "An original reference is KX304. A visual check sees KX340 entered. A separate double-entry attempt produces KX304 and KX340. Describe how each check detects an error and how it should be resolved.", ids(8, 1, 2), ["The visual check compares the entered reference with the original and spots the transposed digits.", "The computer compares the two independently entered strings and flags their mismatch.", "Consult the original source, correct the entry and compare again."], "Do not choose the first entry as correct without checking the source."),
      q(5, 7, "Calculate the parity bit for seven data bits 1100101 under even parity, then under odd parity. Explain why flipping two bits may evade a byte parity check.", ids(8, 3, 5), ["The data has four 1 bits, so the even-parity bit is 0.", "The odd-parity bit is 1, giving five 1 bits in total.", "Two flips change the count by an even amount, preserving its odd/even parity."], "Count the parity bit in the total."),
      q(5, 8, "Calculate the even-parity row for these three complete eight-bit rows: 11100001, 01010101, 00110011. Then suppose only row 2 becomes 01011101. Identify the changed bit and describe the correction.", ids(8, 3), ["The column parity row is 10000111.", "Only row 2 fails its parity check.", "Column 5 fails, locating the error at row 2 column 5.", "Flip that bit from 1 to 0 and recheck both row and column parity."], "Use column counts rather than adding the rows as binary integers."),
      q(5, 9, "Calculate a checksum for data bytes 200,45,30 using sum modulo 256. If the receiver gets 200,46,30 with the original checksum, calculate its check value and state the decision.", ids(8, 4), ["The original sum is 275, giving checksum 19.", "The received sum is 276, giving checksum 20.", "20 differs from transmitted 19, so reject the block or request retransmission."], "Apply the same modulo rule at both ends."),
      q(5, 10, "Explain why both identical double-entry values and matching transfer checksums can still occur when the information is wrong.", ids(8, 5), ["The operator can repeat the same incorrect entry, producing identical copies.", "Different data blocks can produce the same checksum, so a changed block may escape detection."], "Agreement is evidence from a particular check, not proof of truth."),
    ],
    authoredExamQuestions: [
      e(5, 1, "A membership form requires a non-blank member ID that exists in a stored membership file, a six-character booking code, and an age from 5 to 18 inclusive. Identify one validation check for each requirement. Explain why an age of 12 may pass even if the member is actually 14.", ids(7, 2, 4, 5, 6, 9), ["Use a presence check for the required member ID.", "Use an existence check against the membership file.", "Use a length check for the six-character booking code.", "Use a range check with inclusive bounds 5 and 18 for age.", "12 meets the permitted range, but the rule does not establish the member's true age."], "An existence check needs the specified stored file, not just a plausible identifier."),
      e(5, 2, "A reference has data digits 2468. Using weights 3,1,3,1, its final digit must make the weighted total a multiple of 10. Calculate the check digit. A clerk then enters the same incorrect full reference twice. Explain why the two checking methods may give different results.", [...ids(7, 8), ...ids(8, 2, 5)], ["The weighted total is 6 + 4 + 18 + 8 = 36.", "The required check digit is 4, producing 24684.", "Double entry accepts matching copies even when the same mistake is repeated.", "The check-digit rule may reject those copies if their supplied final digit fails the recalculated rule."], "Do not claim every possible wrong reference is detected by a check digit."),
      e(5, 3, "A transfer uses even parity and a separate sum-modulo-256 checksum. Explain why 10101100 passes byte parity, why four flipped rectangle-corner bits may escape block parity, and why changing data bytes 40,50,60 to 41,49,60 escapes this checksum.", ids(8, 3, 4, 5), ["10101100 contains four 1 bits, so its complete group has even parity.", "Each affected row and column in the rectangle has two changed bits and retains its parity.", "Both byte lists total 150 and therefore have checksum 150 modulo 256.", "The checks can agree despite changed data, so passing them is not a guarantee of an error-free transfer."], "Explain each failure mechanism rather than saying all checks are unreliable."),
    ],
    summary: [["Validation", "Test bounds, pattern, length, presence, lookup membership and a stated check-digit rule."], ["Entry verification", "Compare with the source or compare two independent entries."], ["Byte and block parity", "Count all 1 bits; row and column failures can locate one flipped bit."], ["Checksum", "Calculate, send, recalculate and compare using the same algorithm."], ["Limits", "Valid values can be false; agreeing checks can miss some errors."]],
  },
};

export function authorSection6Lesson(source) {
  if (source.section !== 6) return source;
  const n = source.originalLesson === 31 ? 1 : source.originalLesson === 32 ? 3 : source.originalLesson === 34 ? 5 : source.syllabusIds.includes("S6.03") ? 2 : 4;
  const authored = structuredClone(lessons[n]);
  return {
    ...source, ...authored, summaryMode: "authored",
    diagnostic: { prompt: authored.units[0].checkpoint.prompt, answer: authored.units[0].checkpoint.answer },
    teachingCheckpoints: n === 5
      ? ["Work through validation choices, then attempt practice Q1–Q5 before opening the answers.", "Compare the entry methods with Q6. Trace every bit in the parity diagrams before Q7–Q8.", "Calculate both checksum values in Q9 and discuss the limitations in Q10. Complete the three independent exam tasks."]
      : ["Pause at each knowledge-unit check before revealing its answer.", "Use the practice tasks to check mechanisms, then attempt the independent exam questions with marking points closed."],
    sources: ["Cambridge 9618 2027–2029 syllabus, Section 6.1 Data Security and Section 6.2 Data Integrity.", "Original teaching examples, practice and marking points; no past-paper question is reproduced."],
  };
}
